{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening hardware, assemble it at a marked spot on the workbench, then return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workbench",
        "entity_kind": "OBJECT",
        "function": "The wooden table surface where the task is performed.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["table", "desk", "workbench"],
        "required_properties": ["flat surface", "stable"]
      },
      {
        "id": "fastening_location",
        "entity_kind": "REGION",
        "function": "The specific marked area on the workbench where the fastening occurs.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": ["surface spot", "hole", "joint area"],
        "required_properties": ["accessible", "suitable for fastening"]
      },
      {
        "id": "fastening_components",
        "entity_kind": "OBJECT",
        "function": "The hardware pieces (screws, nuts, etc.) required to join the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screw", "bolt", "nut", "washer"],
        "required_properties": ["compatible with fastening location"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to drive the fastening components.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": ["screwdriver", "wrench", "drill"],
        "required_properties": ["capable of driving fasteners"]
      }
    ],
    "functional_relations": [
      {
        "id": "location_on_workbench",
        "relation": "is situated on",
        "participant_roles": ["fastening_location", "workbench"]
      ,
        "required": true
      },
      {
        "id": "tool_secures_parts",
        "relation": "secures via",
        "participant_roles": ["fastening_tool", "fastening_components", "fastening_location"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "locate_components",
        "operation": "search and retrieve",
        "participant_roles": ["fastening_components", "workbench", "fastening_tool"]
      ,
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "drive and attach",
        "participant_roles": ["fastening_tool", "fastening_components", "fastening_location"]
      ,
        "operation_count": 1
      },
      {
        "id": "return_tool",
        "operation": "place down",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workbench": [
        {
          "label": "Wooden table",
          "visual_description": "Central wooden table with drawers and legs."
        }
      ],
      "fastening_location": [
        {
          "label": "Table surface",
          "visual_description": "The top surface of the wooden table; specific mark not visible."
        }
      ],
      "fastening_components": [
        {
          "label": "Items in tray",
          "visual_description": "Yellow and blue objects in a black tray on the table surface."
        }
      ],
      "fastening_tool": [
        {
          "label": "Items in tray",
          "visual_description": "Yellow and blue objects in a black tray on the table surface; possibly a screwdriver."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "cabinet",
        "label": "Blue cabinet",
        "visual_description": "Tall blue cabinet standing next to the table.",
        "reason": "Closed storage structure that may contain hidden components or tools."
      },
      {
        "id": "left_drawer",
        "label": "Left drawer",
        "visual_description": "Drawer on the left side under the table.",
        "reason": "Closed storage structure that may contain hidden components or tools."
      },
      {
        "id": "right_drawer",
        "label": "Right drawer",
        "visual_description": "Drawer on the right side under the table.",
        "reason": "Closed storage structure that may contain hidden components or tools."
      }
    ],
    "inspection_order": [
      "cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
